//#region src/server/workers-tracing.ts
function normalizeException(error) {
	if (typeof error === "string") return error;
	if (error instanceof Error) return {
		message: error.message,
		name: error.name,
		...error.stack ? { stack: error.stack } : {}
	};
	return String(error);
}
function createWorkersTracingIntegration(tracing) {
	const backendSpan = (span) => ({
		recordException: (error) => span.recordException?.(normalizeException(error)),
		setAttribute: (key, value) => span.setAttribute(key, value)
	});
	return {
		id: "cloudflare-workers",
		enterSpan(descriptor, callback) {
			return tracing.enterSpan(descriptor.name, (span) => {
				for (const [key, value] of Object.entries(descriptor.attributes)) span.setAttribute(key, value);
				return callback(backendSpan(span));
			});
		}
	};
}
//#endregion
export { createWorkersTracingIntegration };
